    const pl = S.sc.plans[p.key];
    if (p.key === part.key || !pl) return;
    const tl = (pl.tasks || []).map((t) => `${t.id}: ${t.title} -> ${t.files.join(', ')}`).join('\n');
    out += `--- ${p.key} (${p.role}) ---\n${clip(pl.md, SC_LIM.md)}\nTASKS:\n${tl || '(none)'}\n`;
