  (a.missing || []).forEach((f) => out.push('declared file not written: ' + f));
  (a.checks || []).filter((c) => c.code !== 0).forEach((c) => out.push(`check failed (${c.cmd}) exit ${c.code}: ${clip(c.out, 600)}`));
