      case 'recall':
        return execCmd(S, memCmd(S, `recall ${S.agent} ${S.scopeKey} 12${S.sc && S.sc.conv ? ' ' + S.sc.conv : ''}`));

      case 'brief':
        S.action = 'ministral';
        S.req = chat(S.ctx.MEMORY, `BRIEF for scope ${S.scopeKey} (agent ${S.agent}).\nEntries:\n${clip(S.memraw, LIM.memo)}`, TOK.brief, 0.1);
