}
function scKickText(S) {
  const k = S.sc.kick || {};
  const crit = Object.keys(k.criteria || {}).map((r) => `${r}: ${(k.criteria[r] || []).join(' | ')}`).join('\n');
  return `GOAL: ${k.goal || S.sc.sp.brief}\nCRITERIA:\n${crit || '(none)'}\nRISKS: ${k.risks || '(none)'}`;
}
function scPeers(S, part) {
