  switch (S.step) {
    case 'load_ctx': {
      if (err || !text.includes('=====SLICES=====')) { S.abort = 'ctx.sh failed: ' + (err || 'no output'); S.step = 'done'; return S; }
      S.ctx = ctxSections(text);
