}
function scClaimed(S, part) {
  const m = {};
  S.sc.sp.parts.forEach((p) => {
    const pl = S.sc.plans[p.key];
    if (p.key !== part.key && pl && pl.tasks) pl.tasks.forEach((t) => t.files.forEach((f) => { m[f] = p.key; }));
  });
