    case 'sc_open': return execCmd(S, memCmd(S, `conv-open ${sp.id} ${b64(sp.id + ': ' + sp.title)}`));

    case 'sc_resume': {
      const files = sp.parts.map((p) => `"${root}/docs/agents/${p.role}/${p.slice}.tasks.json"`).join(' ');
