      return null;
    }
    case 'sc_part_go':
      S.agent = sc.part.role; S.scopeKey = sp.id + '/' + sc.part.slice; S.afterRecall = 'sc_plan_call'; S.step = 'recall';
      return null;
    case 'sc_plan_call':
      S.action = 'deepseek';
